CALL {
  MATCH (ch:CrowdHour) WHERE ch.camera_location CONTAINS 'keynote' AND ch.hour_utc >= '2025-12-08T00:00:00Z' AND ch.hour_utc < '2025-12-09T00:00:00Z'
  RETURN substring(ch.hour_utc, 0, 10) + ' ' + substring(ch.hour_utc, 11, 2) AS hour, avg(ch.avg_hc) AS avg_attendance
}
RETURN hour, avg_attendance ORDER BY hour
